def git(*a): return subprocess.check_output(["git",*a])
def sha(b): return hashlib.sha256(b).hexdigest()
immutable={}
for p in ["docs/agent/implementation-state.json","docs/agent/implementation-permissions.json","scripts/implementation-loop.py","scripts/implementation-evidence.py","scripts/implementation-resources.py"]:
 b=pathlib.Path(p).read_bytes(); assert b==git("show",base+":"+p),p; immutable[p]=sha(b)
base_paths=set(git("ls-tree","-r","--name-only",base,"docs/agent/implementation-runs").decode().splitlines())
records={}
for pin in [base]+pins:
 paths=set(git("ls-tree","-r","--name-only",pin,"docs/agent/implementation-runs").decode().splitlines())
 checked=[]
 for p in sorted(paths if pin==base else paths-base_paths):
  b=git("show",pin+":"+p); assert pathlib.Path(p).read_bytes()==b,p; checked.append(p)
 records[pin]={"count":len(checked),"pathsDigest":sha("\n".join(checked).encode())}
server={}
for p in git("ls-tree","-r","--name-only",base,"server/src").decode().splitlines():
 b=pathlib.Path(p).read_bytes(); assert b==git("show",base+":"+p),p; server[p]=sha(b)
paths=set(git("diff",base,"--name-only").decode().splitlines()+git("ls-files","--others","--exclude-standard").decode().splitlines())
inputs={p:sha(pathlib.Path(p).read_bytes()) for p in sorted(paths) if "/src/" in p and pathlib.Path(p).is_file()}
suites={}
for name in ["protocol-junit.json","native-junit.json"]:
 values=json.loads(pathlib.Path("docs/agent/implementation-runs/managed-20261023-integrate-core-01",name).read_text()); totals=dict(tests=0,failures=0,errors=0,skipped=0)
 for v in values.values():
  raw=base64.b64decode(v["base64"]); assert sha(raw)==v["sha256"]; root=E.fromstring(raw)
  for k in totals: totals[k]+=int(root.attrib.get(k,0))
 suites[name]=totals
assert not git("diff","--name-only","--diff-filter=U")
assert git("rev-parse","MERGE_HEAD").decode().strip()==pins[-1]
print(json.dumps(dict(base=base,pins=pins,immutable=immutable,originalReports=records,preservationScope="All base reports plus incoming new original report/evidence paths; older inherited drafts remain in pinned ancestry, never overwrite newer base records.",serverSourceByteIdenticalToBase=server,checkedInputSha256=inputs,junitTotals=suites,head=git("rev-parse","HEAD").decode().strip(),mergeHead=pins[-1]),indent=2))
